function parseWire(stdout) {
  let rest = stdout;
  let header = '';
  while (rest.startsWith('HTTP/')) {
    const match = /\r?\n\r?\n/.exec(rest);
    if (!match) throw new Error('HTTP header boundary missing');
    header = rest.slice(0, match.index);
    rest = rest.slice(match.index + match[0].length);
  }
  const lines = header.split(/\r?\n/);
  const status = Number(lines.shift()?.split(' ')[1]);
  const headers = Object.fromEntries(lines.flatMap((line) => {
    const colon = line.indexOf(':');
    return colon < 0 ? [] : [[line.slice(0, colon).toLowerCase(), line.slice(colon + 1).trim()]];
  }).filter(([key]) => !['set-cookie', 'cookie'].includes(key)));
  return { status, headers, body: rest };
}

async function fetchPublic(url) {
  const { stdout } = await execute('curl.exe', [
    '--silent', '--show-error', '--max-time', '20', '--max-filesize', String(MAX_BYTES),
    '--include', '--user-agent', USER_AGENT, url,
  ], { maxBuffer: MAX_BYTES + 100_000, timeout: 25_000 });
  return parseWire(stdout);
}

/** Uses only the matching generic-agent group; never impersonates a crawler with broader permissions. */
function isAllowed(text, pathname) {
  let agents = [];
  let hadRule = false;
  const rules = [];
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.replace(/#.*/, '').trim();
    const [name, ...rest] = line.split(':');
    const value = rest.join(':').trim();
    if (name?.toLowerCase() === 'user-agent') {
      if (hadRule) { agents = []; hadRule = false; }
      agents.push(value.toLowerCase());
    } else if (['allow','disallow'].includes(name?.toLowerCase())) {
      hadRule = true;
      if (agents.includes('*') && value) rules.push({ value, allow: name.toLowerCase() === 'allow' });
    }
  }
  const matches = rules.filter(({ value }) => {
    const escaped = value.replace(/[.+?^${}()|[\]\\]/g, '\\$&').replaceAll('*', '.*');
    return new RegExp(`^${escaped}`).test(pathname);
  }).sort((a,b) => b.value.length - a.value.length || Number(b.allow) - Number(a.allow));
  return matches[0]?.allow ?? true;
}

async function robotsFor(origin) {
  if (domains.has(origin)) return domains.get(origin);
  const url = `${origin}/robots.txt`;
  try {
    const response = await fetchPublic(url);
    const id = `robots-${new URL(origin).hostname.replaceAll('.', '-')}`;
    await save(id, 'response.txt', response.body);
    await save(id, 'response.meta.json', { url, status: response.status, headers: response.headers, fetchedAt: new Date().toISOString() });
    const policy = { text: response.status === 200 ? response.body : '', verified: [200,404].includes(response.status), url };
    domains.set(origin, policy);
    return policy;
  } catch {
    const policy = { text: '', verified: false, url };
    domains.set(origin, policy);
    return policy;
  }
}

