          const extension = /json/.test(record.contentType ?? '') ? 'json' : /html/.test(record.contentType ?? '') ? 'html' : 'txt';
          record.sample = `data/fixtures/${id}/response.${extension}`;
          await save(id, `response.${extension}`, response.body);
        }
        record.reason = 'Fetched; reuse license, geography, schema and field mapping require review before connection';
      }
      await save(id, 'response.meta.json', record);
    } catch (error) {
      record.reason = error instanceof Error ? error.message.replace(/\r?\n/g, ' ').slice(0,300) : 'Fetch failed';
    }
  }
  responses.push(record);
  await save('discovery', 'external.sources.json', { schemaVersion: 1, capturedAt: new Date().toISOString(), sources: responses });
  process.stdout.write(`${id}: ${record.httpStatus ?? 'not fetched'} ${record.reason.slice(0,90)}\n`);
  await new Promise((resolve) => setTimeout(resolve, PAUSE_MS));
}

await mkdir(new URL('data/sources/', ROOT), { recursive: true });
await writeFile(new URL('data/sources/wuerzburg.external.sources.json', ROOT), `${JSON.stringify({ schemaVersion: 1, sources: responses }, null, 2)}\n`);

import { readFile, writeFile } from 'node:fs/promises';

import { isPlainObject } from '../../src/lib/utils';
import { migrateCategoryProps } from '../../src/modules/component-platform/domain/components/legacy-component-props';

const MAX_DEPTH = 12;
const MAX_NODES = 500;
const MAX_BYTES = 1_000_000;
let visited = 0;

function migrateNode(raw: unknown, depth: number): unknown {
  visited += 1;
  if (depth > MAX_DEPTH || visited > MAX_NODES) {
    throw new Error('Page exceeds builder migration bounds');
  }
  if (!isPlainObject(raw)) {
    throw new Error('Expected a page node object');
  }
  const type = raw['type'];
  return {
    ...raw,
    ...(typeof type === 'string' && 'props' in raw ? { props: migrateCategoryProps(type,raw['props']) } : {}),
    ...(Array.isArray(raw['children']) ? { children: raw['children'].map((child: unknown) => migrateNode(child,depth+1)) } : {}),
  };
}

const [input,output] = process.argv.slice(2);
if (input === undefined || output === undefined) {
  throw new Error('Usage: tsx scripts/wuerzburg/migrate-props.ts <page-config.json> <new-output.json>');
}
const source = await readFile(input);
if (source.byteLength > MAX_BYTES) {
  throw new Error('Page exceeds builder migration size bound');
}
const raw: unknown = JSON.parse(source.toString('utf8'));
const migrated = migrateNode(raw,0);
await writeFile(output,`${JSON.stringify(migrated,null,2)}\n`,{flag:'wx'});
process.stdout.write(`Wrote a reviewable migration for ${visited} nodes. Existing input and published releases remain unchanged.\n`);

import 'dotenv/config';
import '../lib/server-runtime';

import { Client } from 'pg';

import { WUERZBURG_WEBSITE_ID } from '../../prisma/seed/wuerzburg-manifest';
import { serverEnv } from '../../src/lib/config/server';
import { advisoryLock, db, disconnectDb } from '../../src/lib/db';

const ACCOUNTS = ['platform_admin','admin','editor','contributor','viewer','employee'].map((role) => `wuerzburg-demo-${role}`);

if (serverEnv.NODE_ENV === 'production') {
  throw new Error('Reference-city reset is forbidden in production');
}
if (!process.argv.includes('--confirm-wuerzburg')) {
  throw new Error('Reset removes only the reference tenant. Pass --confirm-wuerzburg to execute.');
}

try {
  await db.transaction(async (tx) => {
    await advisoryLock(tx, 'seed:wuerzburg');
    await tx.orm.public.Website.where({ id: WUERZBURG_WEBSITE_ID, tenantId: WUERZBURG_WEBSITE_ID }).updateAndCount({ publishedReleaseId: null });
    await tx.orm.public.Website.where({ id: WUERZBURG_WEBSITE_ID, tenantId: WUERZBURG_WEBSITE_ID }).deleteAndCount();
    await tx.orm.public.Membership.where({ tenantId: WUERZBURG_WEBSITE_ID }).deleteAndCount();
    await tx.orm.public.Invitation.where({ tenantId: WUERZBURG_WEBSITE_ID }).deleteAndCount();
    for (const actorId of ACCOUNTS) {
      await tx.orm.public.Membership.where({ actorId, tenantId: 'platform' }).deleteAndCount();
    }
  });
  if (serverEnv.AUTH_DATABASE_URL !== undefined) {
    const client = new Client({ connectionString: serverEnv.AUTH_DATABASE_URL });
    await client.connect();
    try {
      await client.query('DELETE FROM "user" WHERE id = ANY($1::text[])', [ACCOUNTS]);
    } finally {
      await client.end();
    }
  }
  process.stdout.write('Removed only the Würzburg reference tenant and its exact fictional identity IDs.\n');
} finally {
  await disconnectDb();
}

