import type { ValidationAppError } from '@lib/errors';

import type {
  ContentKind,
  ContentOf,
  ContentSourceError,
  RenderMode,
} from './component-platform-constraints';
import type { ContentProvenance } from '../../domain/models/content-provenance';


/**
 * Where the records came from, so the UI can be honest about it.
 * `sample` carries the error code that made the editor fall back, or `null`
 * when nothing is bound yet.
 */
export type ContentOrigin =
  | { readonly kind: 'live'; readonly sources?: readonly ContentProvenance[]; readonly rejected?: number }
  | { readonly kind: 'unbound' }
  | { readonly kind: 'sample'; readonly cause: string | null };

export interface ContentListView<K extends ContentKind> {
  readonly items: ReadonlyArray<ContentOf<K>>;
  readonly origin: ContentOrigin;
  /** More relevant records existed than the limit allowed. */
  readonly truncated: boolean;
}

/** What a data component asks for. Plain strings: props are untrusted until the use case parses them. */
export interface ContentListRequest<K extends ContentKind> {
  readonly kind: K;
  readonly mode: RenderMode;
  /** From the render context, never from component props. */
  readonly websiteId: string;
  readonly datasetId?: string | undefined;
  /** Further datasets read together with `datasetId`; all must provide the same kind. */
  readonly additionalDatasetIds?: readonly string[] | undefined;
  readonly category?: string | undefined;
  /** How many records are shown; the Limit an editor set. Bounded by the kind's scale. */
  readonly limit?: number | undefined;
  /** Where the window starts, for a view the visitor moves (a chart panned, a map moved). */
  readonly offset?: number | undefined;
}

/**
 * Why a list could not be produced. A malformed website id is a bug
 * upstream, so it is reported as validation, not as "not found".
 */
export type ContentLoadError = ContentSourceError | ValidationAppError;

/** What the editor asks for to offer category choices. Plain strings: ids and kinds come from the route. */
export interface ContentCategoriesRequest {
  /** From the authorized page, never from a request body. */
  readonly websiteId: string;
  /** The kinds whose sample categories are needed (components that are not bound yet). */
  readonly kinds: readonly string[];
  readonly datasets: ReadonlyArray<{ readonly id: string; readonly kind: string }>;
}

/** Distinct category values, sorted. */
export interface ContentCategoriesView {
  readonly byDataset: Readonly<Record<string, readonly string[]>>;
  readonly sampleByKind: Readonly<Record<string, readonly string[]>>;
}

import type { NotFoundAppError } from '@lib/errors';
import { err, ok } from '@lib/result';
import type { AppResult } from '@lib/result';

import { readLegacyComponentDefaults } from '../../domain/components/legacy-component-props';
import { componentNotRegistered } from '../../domain/errors/component-platform-errors';

import type { PublicComponentPlatformDependencies } from '../component-platform-dependencies';

export interface GetComponentDefaultPropsInput {
  readonly type: string;
  readonly version: number;
}

/**
 * The props a freshly created node of `type` starts with at exactly
 * `version`: what a release's migration needs as the BASE of its three-way
 * merge. What a "default" is stays defined here, so no consumer reads the
 * definition itself.
 *
 * `null` means the version is known to be gone: only the current version of
 * a component is retained for now, and a consumer must report an older one
 * as unresolvable instead of guessing. An unregistered type is an error the
 * caller decides how to treat.
 *
 * @authorization public Reads the component catalog, which is code and contains nothing per tenant.
 * @rate-limit none Reads the component catalog, which is code and the same for everyone; it touches no store.
 */
export class GetComponentDefaultProps {
  constructor(private readonly deps: PublicComponentPlatformDependencies) {}

  execute(
    input: GetComponentDefaultPropsInput,
  ): AppResult<Readonly<Record<string, unknown>> | null, NotFoundAppError> {
    const definition = this.deps.registry.find(input.type);
    if (definition === undefined) {
      return err(componentNotRegistered());
    }
    return ok(definition.version === input.version ? definition.defaultProps : readLegacyComponentDefaults(input.type, input.version));
  }
}

import type { ConflictAppError, InfrastructureAppError, NotFoundAppError } from '@lib/errors';
import type { AppResultAsync } from '@lib/result';

import type { ContentKind, ContentOf } from '../content/content-definitions';
import type { ContentProvenance } from '../models/content-provenance';
import type { DatasetId, WebsiteId } from '../models/ids';

/** Why a source could not deliver: all three are outcomes callers can tell apart. */
export type ContentSourceError = NotFoundAppError | ConflictAppError | InfrastructureAppError;

export interface ContentRequest<K extends ContentKind> {
  readonly kind: K;
  readonly datasetId: DatasetId;
  /** From the render context, never from component props: the dataset must belong to this website. */
  readonly websiteId: WebsiteId;
  readonly window: ContentWindow;
}

/** Which records of the dataset are wanted: `limit` from `offset`. */
export interface ContentWindow {
  readonly limit: number;
  readonly offset: number;
}

export interface ContentBatch<K extends ContentKind> {
  readonly provenance?: ContentProvenance;
  readonly rejected?: number;
  /** Only records that satisfy the canonical contract. Rejected records are the adapter's to report. */
  readonly items: ReadonlyArray<ContentOf<K>>;
  /** The dataset holds records beyond the window: the view shows part of it. */
  readonly hasMore: boolean;
}

/**
 * Delivers canonical records from a bound dataset. Adapters translate every
 * transport failure into this module's own error kinds and never return a
 * record that failed its contract.
 */
export interface ContentSource {
  list<K extends ContentKind>(
    request: ContentRequest<K>,
  ): AppResultAsync<ContentBatch<K>, ContentSourceError>;
}

